package com.shraddha.assistant

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build

/** Notifications generated by explicit user-enabled background features. */
object ShraddhaEventNotifications {
    private const val CHANNEL_ID = "shraddha_events"
    private const val ID_NOTIFICATION_WAKE = 8260
    private const val ID_BATTERY_LOW = 8261
    private const val ID_BATTERY_FULL = 8262

    private fun manager(context: Context): NotificationManager =
        context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

    private fun ensureChannel(context: Context) {
        if (Build.VERSION.SDK_INT >= 26) {
            manager(context).createNotificationChannel(
                NotificationChannel(CHANNEL_ID, "Shraddha AI alerts", NotificationManager.IMPORTANCE_HIGH).apply {
                    description = "User-enabled notification and battery alerts from Shraddha AI"
                    setShowBadge(true)
                }
            )
        }
    }

    fun post(context: Context, id: Int, title: String, text: String, activateVoice: Boolean = false) {
        try {
            ensureChannel(context)
            val open = Intent(context, MainActivity::class.java).apply {
                flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP
                if (activateVoice) putExtra(WakeActivationService.EXTRA_AUTO_LISTEN, true)
            }
            val pending = PendingIntent.getActivity(
                context, id, open,
                PendingIntent.FLAG_UPDATE_CURRENT or if (Build.VERSION.SDK_INT >= 23) PendingIntent.FLAG_IMMUTABLE else 0
            )
            @Suppress("DEPRECATION")
            val builder = if (Build.VERSION.SDK_INT >= 26) Notification.Builder(context, CHANNEL_ID) else Notification.Builder(context)
            manager(context).notify(id, builder.setSmallIcon(android.R.drawable.ic_btn_speak_now)
                .setContentTitle(title).setContentText(text).setStyle(Notification.BigTextStyle().bigText(text))
                .setContentIntent(pending).setAutoCancel(true).setCategory(Notification.CATEGORY_STATUS).build())
        } catch (_: SecurityException) {
            // Android 13+: notifications may be disabled or permission may not have been granted.
        } catch (_: Exception) {
        }
    }

    fun notificationWake(context: Context) = post(
        context, ID_NOTIFICATION_WAKE, "Shraddha AI · Notification received",
        "Tap to open Shraddha and start a voice conversation. Notification content is not read or uploaded.",
        activateVoice = true
    )

    fun batteryLow(context: Context) = post(
        context, ID_BATTERY_LOW, "Shraddha AI · Battery low",
        "Your phone reported low battery. Consider connecting the charger."
    )

    fun batteryFull(context: Context) = post(
        context, ID_BATTERY_FULL, "Shraddha AI · Fully charged",
        "Your phone battery has reached 100% while charging."
    )

    fun clearBatteryLow(context: Context) {
        try { manager(context).cancel(ID_BATTERY_LOW) } catch (_: Exception) {}
    }
}
